import{_ as o,o as a,c as i,a7 as t}from"./chunks/framework.Du_9D64Q.js";const u=JSON.parse(`{"title":"What does “Incompatible API version” mean when loading a plugin?","description":"Troubleshooting 'Incompatible API version' when loading a plugin.","frontmatter":{"title":"What does “Incompatible API version” mean when loading a plugin?","outline":"deep","description":"Troubleshooting 'Incompatible API version' when loading a plugin.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/faq/plugins/incompatibleapi"}]]},"headers":[],"relativePath":"docs/faq/plugins/incompatibleapi.md","filePath":"docs/faq/plugins/incompatibleapi.md","lastUpdated":1790689997000}`),n={name:"docs/faq/plugins/incompatibleapi.md"};function s(r,e,l,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="what-does-incompatible-api-version-mean-when-loading-a-plugin" tabindex="-1">What does “Incompatible API version” mean when loading a plugin? <a class="header-anchor" href="#what-does-incompatible-api-version-mean-when-loading-a-plugin" aria-label="Permalink to &quot;What does &quot;Incompatible API version&quot; mean when loading a plugin?&quot;">​</a></h1><p>This means that the version of the plugin currently installed is not compatible with the server. This might be because your version of Axolotl-PM is out of date, or because the plugin itself is out of date.</p><h2 id="why-does-it-matter-what-version-i-m-using" tabindex="-1">Why does it matter what version I’m using? <a class="header-anchor" href="#why-does-it-matter-what-version-i-m-using" aria-label="Permalink to &quot;Why does it matter what version I&#39;m using?&quot;">​</a></h2><p>New features are added to the API over time, and old ones may be deprecated. In addition, in a major version bump (e.g. 4.x -&gt; 5.x), there may be <strong>backwards-incompatible changes</strong> (sometimes referred to as <em>BC breaks</em>) which prevent plugins working on different major versions.</p><p>Plugins declare which API versions they support to make sure their plugins fail gracefully instead of crashing your server or making it do something unexpected.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>You can learn more about how API versions work <a href="/website/previews/a0ba0a257939/docs/developers/plugin-docs/api-version-spec">here</a>.</p></div><h2 id="what-can-i-do" tabindex="-1">What can I do? <a class="header-anchor" href="#what-can-i-do" aria-label="Permalink to &quot;What can I do?&quot;">​</a></h2><p>Check for an updated version of the plugin, or ask the plugin developer to update it.</p><p>If you’re feeling adventurous, you could try updating the code yourself to work on the version of Axolotl-PM you’re using. Check out the <a href="/website/previews/a0ba0a257939/docs/developers/plugin-docs-index">plugin development docs</a>. Also, consider joining our <a href="https://discord.gg/vrPugybpJF" target="_blank" rel="noreferrer">Discord</a> server so that you can ask other developers for help.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Simply bumping the plugin’s declared API version is often not enough to update a plugin. The plugin might still crash or not work as expected. Use of so-called “API updaters” is discouraged.</p></div>',10)])])}const g=o(n,[["render",s]]);export{u as __pageData,g as default};
